window.RP_SESSION={"id":"S-c6a56706ca08","messages":[{"id":"RP-II-0098463","time":"2026-05-09T22:59:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"흠...\"\n\n코난은 한창 책과 씨름을 하고 있었다. 도통 이해가 되지를 않는 구문. 글을 읽고 이야기 하는 것은 슬슬 익숙하지만 그렇다고 그 속 뜻을 이해하는 것은 아니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098464","time":"2026-05-09T23:02:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"봄이 왔는데 생명이 아니라 고통이 깨어난다.\n사람들은 도시 속에서 죽은 자처럼 걸어 다닌다.\n과거의 신화와 현재의 일상이 뒤섞이고,\n마지막에는 비처럼 구원의 암시가 오지만, 그것조차 완전하지 않다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098465","time":"2026-05-09T23:02:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-II-0098466","time":"2026-05-09T23:02:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"성경은 읽어도 도통 이해가 되지를 않는다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098467","time":"2026-05-09T23:04:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"봄은 싱그러운 생명이 있으며 도시의 사람들은 살아가느라 바쁘지 않던가? 신화와 일상? 그들은 꿈에서 살아가는가? 구원의 암시는 또 무엇인가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098468","time":"2026-05-09T23:04:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 계속해서 고민하고 있습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098469","time":"2026-05-09T23:04:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"들린 책은 아주 낡아보이는 라운데라 교리를 담은 책으로 보입니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098470","time":"2026-05-09T23:05:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"성경은 아니지만.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098471","time":"2026-05-09T23:07:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"아니면 내가 모르는 이야기가 있는가? 혹은 반어법인가? 어쩌면...\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098472","time":"2026-05-09T23:07:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098473","time":"2026-05-09T23:07:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'코난 발토르'의 지능 판정 :\n[11] + [0] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0098474","time":"2026-05-09T23:08:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"당장은 내가 모를 이야기다. 언젠가는 알게될지도 모른다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098475","time":"2026-05-09T23:08:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 도서관 구석에서 발견한 이상한 책을 덮고 다시 원래 자리에 돌려뒀습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098476","time":"2026-05-09T23:10:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"루체 덕에 옷을 사자 성벽 공사 말고도 시장 치안 유치 등 자잘한 의뢰에 참가할 수 있게 되고 아도니스가 추천해준 창고의 책을 읽으니 책을 살 일도 적어졌습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098477","time":"2026-05-09T23:10:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"덕분에 이전과 다르게 제법 묵직해진 은화주머니를 보고서 코난은 다시금 생각합니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098478","time":"2026-05-09T23:11:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"돈이란 무엇이고. 이렇게 많은 것을 모으면 뭘 할 수 있는거지?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098479","time":"2026-05-09T23:11:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 질문을 위해 자리를 떠납니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098480","time":"2026-05-09T23:11:00+09:00","room":"RP II","name":"코난 발토르","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0098481","time":"2026-05-09T23:11:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
